-- Tanpa baris ini klien mysql memakai charset bawaan sistem (kerap latin1),
-- sehingga tanda derajat pada `lokasi_arp` tersimpan ganda ("00Â° 55'").
-- Akibatnya koordinat gagal dibaca arp_to_latlng() — peta pada halaman
-- Daftar Bandar Udara kosong dan tab "Bandar Udara Terdekat" ikut kosong.
SET NAMES utf8mb4;

-- Tabel anak pada database/migrate-detail-bandara.sql memiliki kunci asing
-- ke tabel ini, dan kunci itu menahan DROP di bawah. Bila memuat ulang berkas
-- ini pada basis data yang sudah dimigrasi, hapus dulu tabel anaknya lalu
-- jalankan kembali migrasinya:
--   mysql -u root NAMA_DB -e "DROP TABLE IF EXISTS bandara_rute, bandara_fasilitas_udara,
--     bandara_fasilitas_darat, bandara_fasilitas_umum, bandara_galeri;"
--   mysql -u root --default-character-set=utf8mb4 NAMA_DB < database/bandaras.sql
--   mysql -u root --default-character-set=utf8mb4 NAMA_DB < database/migrate-detail-bandara.sql
DROP TABLE IF EXISTS bandaras;
CREATE TABLE  bandaras (`id` INT(11) NOT NULL AUTO_INCREMENT PRIMARY KEY,
`nama` VARCHAR(500) NULL,
`kode_iata` VARCHAR(3) NULL,
`kode_icao` VARCHAR(4) NULL,
`alamat` VARCHAR(500) NULL,
`email` VARCHAR(500) NULL,
`fax` VARCHAR(500) NULL,
`kelurahan_desa` VARCHAR(500) NULL,
`kecamatan` VARCHAR(100) NULL,
`kabupaten_kota` VARCHAR(100) NULL,
`provinsi` VARCHAR(100) NULL,
`kantor_otoritas` VARCHAR(500) NULL,
`kelas` VARCHAR(100) NULL,
`latitude` VARCHAR(500) NULL,
`longitude` VARCHAR(500) NULL,
`lokasi_arp` VARCHAR(500) NULL,
`pengelola` VARCHAR(500) NULL,
`jumlah_pesawat` INT(11) NULL,
`telepon` VARCHAR(100) NULL,
`tipe` VARCHAR(100) NULL,
`website` VARCHAR(100) NULL,
`jumlah_penumpang` INT(11) NULL DEFAULT 0,
`jumlah_kargo` INT(11) NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

